"use strict";const e=require("../common/vendor.js"),r=require("./request.js");exports.changePassword=function(e){return r.request({url:"/api/user/password",method:"PUT",data:e})},exports.getUnreadCount=function(){return r.request({url:"/api/user/messages/unread-count",method:"GET"})},exports.getUserInfo=function(){return r.request({url:"/api/user/info",method:"GET"})},exports.updateProfile=function(e){return r.request({url:"/api/user/profile",method:"PUT",data:e})},exports.uploadAvatar=function(r){return new Promise((t,o)=>{const s=e.index.getStorageSync("token");e.index.uploadFile({url:"http://localhost:8080/api/user/avatar",filePath:r,name:"file",header:s?{Authorization:`Bearer ${s}`}:{},success(e){try{const r=JSON.parse(e.data);200===r.code?t(r):o(new Error(r.message))}catch{o(new Error("解析失败"))}},fail:()=>o(new Error("上传失败"))})})};
